function formatRupees(value: number) {
  const normalized = Math.max(0, Math.round(value * 100) / 100);
  return new Intl.NumberFormat("en-IN", {
    minimumFractionDigits: Number.isInteger(normalized) ? 0 : 2,
    maximumFractionDigits: 2,
  }).format(normalized);
}

